create extension if not exists pgcrypto;
create table if not exists public.employees(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,email text not null,role text not null default 'employee' check(role in('admin','employee')),salary numeric(12,2) not null default 0 check(salary>=0),leave_balance numeric(6,2) not null default 21 check(leave_balance>=0),created_at timestamptz not null default now());
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.employees(id),kind text not null check(kind in('sale','followup','collection','other')),customer_name text not null,amount numeric(12,2) not null default 0 check(amount>=0),notes text,created_at timestamptz not null default now());
create table if not exists public.attendance_sessions(id uuid primary key default gen_random_uuid(),token uuid not null unique default gen_random_uuid(),created_by uuid not null references public.employees(id),created_at timestamptz not null default now(),expires_at timestamptz not null default(now()+interval '10 minutes'),active boolean not null default true);
create table if not exists public.attendance(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.employees(id),work_date date not null default(now() at time zone 'Africa/Cairo')::date,check_in_at timestamptz not null default now(),unique(employee_id,work_date));
create table if not exists public.leaves(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.employees(id),start_date date not null,days numeric(6,2) not null check(days>0),leave_type text not null,notes text,covered_days numeric(6,2) not null default 0,uncovered_days numeric(6,2) not null default 0,salary_deduction numeric(12,2) not null default 0,created_by uuid not null references public.employees(id),created_at timestamptz not null default now());
create table if not exists public.advances(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.employees(id),amount numeric(12,2) not null check(amount>0),advance_date date not null default current_date,notes text,created_by uuid not null references public.employees(id),created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.employees where id=auth.uid() and role='admin'); $$;
alter table public.employees enable row level security; alter table public.transactions enable row level security; alter table public.attendance_sessions enable row level security; alter table public.attendance enable row level security; alter table public.leaves enable row level security; alter table public.advances enable row level security;
create policy "employee read own or admin" on public.employees for select to authenticated using(id=auth.uid() or public.is_admin());
create policy "admin manage employees" on public.employees for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "transaction read own or admin" on public.transactions for select to authenticated using(employee_id=auth.uid() or public.is_admin());
create policy "transaction insert own" on public.transactions for insert to authenticated with check(employee_id=auth.uid() or public.is_admin());
create policy "attendance read own or admin" on public.attendance for select to authenticated using(employee_id=auth.uid() or public.is_admin());
create policy "admin read sessions" on public.attendance_sessions for select to authenticated using(public.is_admin());
create policy "admin read leaves" on public.leaves for select to authenticated using(public.is_admin());
create policy "admin read advances" on public.advances for select to authenticated using(public.is_admin());
create policy "admin insert advances" on public.advances for insert to authenticated with check(public.is_admin());
create or replace function public.create_attendance_session() returns jsonb language plpgsql security definer set search_path=public as $$ declare t uuid; begin if not public.is_admin() then raise exception 'العملية للمدير فقط'; end if; update public.attendance_sessions set active=false where active; insert into public.attendance_sessions(created_by,expires_at) values(auth.uid(),now()+interval '10 minutes') returning token into t; return jsonb_build_object('token',t); end; $$;
create or replace function public.mark_attendance(p_token uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare v uuid:=auth.uid(); begin if v is null then raise exception 'سجل الدخول أولًا'; end if; if not exists(select 1 from public.attendance_sessions where token=p_token and active and expires_at>now()) then raise exception 'الكود غير صالح أو انتهت صلاحيته'; end if; insert into public.attendance(employee_id,work_date,check_in_at) values(v,(now() at time zone 'Africa/Cairo')::date,now()) on conflict(employee_id,work_date) do nothing; if not found then return jsonb_build_object('message','تم تسجيل حضورك مسبقًا اليوم'); end if; return jsonb_build_object('message','تم تسجيل الحضور بنجاح'); end; $$;
create or replace function public.record_leave(p_employee_id uuid,p_days numeric,p_type text,p_start_date date,p_notes text default '') returns jsonb language plpgsql security definer set search_path=public as $$ declare e public.employees%rowtype; c numeric; x numeric; ded numeric; begin if not public.is_admin() then raise exception 'العملية للمدير فقط'; end if; if p_days<=0 then raise exception 'عدد الأيام غير صحيح'; end if; select * into e from public.employees where id=p_employee_id for update; if not found then raise exception 'الموظف غير موجود'; end if; c:=case when p_type='unpaid' then 0 else least(e.leave_balance,p_days) end; x:=p_days-c; ded:=round((e.salary/30.0)*x,2); update public.employees set leave_balance=greatest(0,leave_balance-c) where id=p_employee_id; insert into public.leaves(employee_id,start_date,days,leave_type,notes,covered_days,uncovered_days,salary_deduction,created_by) values(p_employee_id,p_start_date,p_days,p_type,p_notes,c,x,ded,auth.uid()); return jsonb_build_object('message','تم التسجيل. من الرصيد: '||c||'، أيام زائدة: '||x||'، خصم تقديري: '||ded||' جنيه'); end; $$;
create or replace function public.add_advance(p_employee_id uuid,p_amount numeric,p_date date,p_notes text default '') returns jsonb language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'العملية للمدير فقط'; end if; if p_amount<=0 then raise exception 'المبلغ غير صحيح'; end if; insert into public.advances(employee_id,amount,advance_date,notes,created_by) values(p_employee_id,p_amount,p_date,p_notes,auth.uid()); return jsonb_build_object('message','تم تسجيل السلفة'); end; $$;
grant execute on function public.is_admin() to authenticated; grant execute on function public.create_attendance_session() to authenticated; grant execute on function public.mark_attendance(uuid) to authenticated; grant execute on function public.record_leave(uuid,numeric,text,date,text) to authenticated; grant execute on function public.add_advance(uuid,numeric,date,text) to authenticated;
